1	use std::env;
2	use std::ffi::{OsStr, OsString};
3	use std::process::ExitCode;
4	
5	#[cfg(unix)]
6	use std::ffi::CString;
7	#[cfg(unix)]
8	use std::os::unix::ffi::OsStrExt;
9	#[cfg(unix)]
10	use std::os::unix::io::RawFd;
11	
12	const VERSION_STRING: &str = "wrapfile 0.1.0";
13	const KEY_LEN: usize = 32;
14	
15	fn main() -> ExitCode {
16	    // args_os (not args): on Unix a key file path may contain bytes that are
17	    // not valid UTF-8, and those are legitimate on-disk names we must accept
18	    // verbatim rather than panic on.
19	    let args: Vec<OsString> = env::args_os().skip(1).collect();
20	
21	    match args.first().map(OsString::as_os_str) {
22	        Some(a) if a == "--version" && args.len() == 1 => {
23	            println!("{VERSION_STRING}");
24	            ExitCode::SUCCESS
25	        }
26	        Some(a) if a == "keygen" => run_keygen(&args[1..]),
27	        _ => {
28	            print_usage();
29	            ExitCode::from(2)
30	        }
31	    }
32	}
33	
34	fn print_usage() {
35	    eprintln!("Usage: wrapfile --version");
36	    eprintln!("       wrapfile keygen <KEY_FILE>");
37	}
38	
39	fn run_keygen(args: &[OsString]) -> ExitCode {
40	    // A leading "--" marks the end of options, allowing a path that starts
41	    // with '-' to be passed (e.g. `wrapfile keygen -- -weird-name`).
42	    let (args, options_ended): (&[OsString], bool) = match args {
43	        [first, rest @ ..] if first == "--" => (rest, true),
44	        _ => (args, false),
45	    };
46	    let path: &OsStr = match args {
47	        [] => {
48	            eprintln!("wrapfile keygen: missing key file path");
49	            print_usage();
50	            return ExitCode::from(2);
51	        }
52	        [p] if options_ended || !starts_with_dash(p) => p,
53	        [p] => {
54	            // render_path already adds the surrounding double quotes when
55	            // the option text needs escaping, so no extra quotes go here.
56	            eprintln!("wrapfile keygen: unknown option {}", render_path(p));
57	            print_usage();
58	            return ExitCode::from(2);
59	        }
60	        _ => {
61	            eprintln!("wrapfile keygen: expected exactly one argument (key file path)");
62	            print_usage();
63	            return ExitCode::from(2);
64	        }
65	    };
66	
67	    match generate_key_file(path) {
68	        Ok(()) => {
69	            println!("Key saved to {}", render_path(path));
70	            ExitCode::SUCCESS
71	        }
72	        Err(e) => {
73	            eprintln!("wrapfile keygen: {e}");
74	            ExitCode::from(1)
75	        }
76	    }
77	}
78	
79	// True if the argument begins with '-'. Checked on the raw bytes so a path
80	// with non-UTF-8 bytes is classified the same as any other name.
81	fn starts_with_dash(arg: &OsStr) -> bool {
82	    arg.as_encoded_bytes().first() == Some(&b'-')
83	}
84	
85	// Render a path for messages only.
86	//
87	// A plain name -- valid UTF-8 with no ASCII control byte, no double quote,
88	// and no backslash -- is shown verbatim, exactly as before. Anything else is
89	// wrapped in double quotes and rendered with escapes:
90	//
91	//   \n \r \t   newline, carriage return, tab (so a name can never break a
92	//              message across lines or smuggle terminal control bytes in)
93	//   \"  \\     double quote and backslash
94	//   \xhh       every other ASCII control byte, and every raw byte that is
95	//              not part of valid UTF-8, as two lowercase hex digits
96	//
97	// Decodable non-ASCII text (e.g. Chinese characters) is kept as-is inside
98	// the quotes. The result therefore never contains a raw ASCII control byte
99	// (the line terminator printed after the message is the only one), and two
100	// different raw names always render differently: a real 0xff byte shows as
101	// `\xff` while a name literally containing those four characters shows as
102	// `\\xff`, and a real newline shows as `\n` while a backslash followed by
103	// `n` shows as `\\n`.
104	//
105	// This string is purely informational -- it is never used to create, look
106	// up, or remove anything. The original OsStr is used for every filesystem
107	// operation, so non-UTF-8 names are still operated on byte for byte.
108	#[cfg(unix)]
109	fn render_path(path: &OsStr) -> String {
110	    const QUOTE: u8 = b'"';
111	    const BACKSLASH: u8 = b'\\';
112	
113	    let bytes = path.as_encoded_bytes();
114	
115	    // Valid UTF-8 with nothing that needs an escape: keep the historical
116	    // bare display (and the bare "Key saved to ..." wording).
117	    if std::str::from_utf8(bytes).is_ok()
118	        && bytes
119	            .iter()
120	            .all(|&b| b >= 0x20 && b != QUOTE && b != BACKSLASH && b != 0x7f)
121	    {
122	        return String::from_utf8(bytes.to_vec()).unwrap();
123	    }
124	
125	    let mut out = String::with_capacity(bytes.len() + 2);
126	    out.push('"');
127	
128	    // Walk the raw bytes, stepping over whole UTF-8 sequences so a valid
129	    // multi-byte character is shown intact while an undecodable byte is
130	    // escaped on its own.
131	    let mut i = 0;
132	    while i < bytes.len() {
133	        let b = bytes[i];
134	
135	        if b < 0x80 {
136	            match b {
137	                b'\n' => out.push_str("\\n"),
138	                b'\r' => out.push_str("\\r"),
139	                b'\t' => out.push_str("\\t"),
140	                QUOTE => out.push_str("\\\""),
141	                BACKSLASH => out.push_str("\\\\"),
142	                // Printable ASCII (0x20..=0x7e except the two handled above)
143	                // is shown as itself.
144	                0x20..=0x7e => out.push(b as char),
145	                // Every remaining ASCII control byte (including NUL and
146	                // DEL) is rendered explicitly.
147	                _ => out.push_str(&format!("\\x{b:02x}")),
148	            }
149	            i += 1;
150	            continue;
151	        }
152	
153	        // Length of the UTF-8 sequence starting here.
154	        let seq_len = if b & 0xe0 == 0xc0 {
155	            2
156	        } else if b & 0xf0 == 0xe0 {
157	            3
158	        } else if b & 0xf8 == 0xf0 {
159	            4
160	        } else {
161	            // 0x80..0xbf continuation byte, or 0xf8..0xff lead: never legal
162	            // here.
163	            1
164	        };
165	
166	        if seq_len > 1
167	            && i + seq_len <= bytes.len()
168	            && std::str::from_utf8(&bytes[i..i + seq_len]).is_ok()
169	        {
170	            // from_utf8 on a maximal, well-formed sequence succeeds; push the
171	            // character as text so e.g. Chinese names keep their glyphs.
172	            out.push_str(std::str::from_utf8(&bytes[i..i + seq_len]).unwrap());
173	            i += seq_len;
174	        } else {
175	            out.push_str(&format!("\\x{b:02x}"));
176	            i += 1;
177	        }
178	    }
179	
180	    out.push('"');
181	    out
182	}
183	
184	// On non-Unix targets keygen never reaches the filesystem; keep the message
185	// rendering lossy-but-inert there (control bytes are still escaped) rather
186	// than duplicating the byte-level renderer.
187	#[cfg(not(unix))]
188	fn render_path(path: &OsStr) -> String {
189	    use std::fmt::Write as _;
190	    let text = path.to_string_lossy();
191	    if text
192	        .chars()
193	        .all(|c| c as u32 >= 0x20 && c != '"' && c != '\\' && c as u32 != 0x7f)
194	    {
195	        return text.into_owned();
196	    }
197	    let mut out = String::with_capacity(text.len() + 2);
198	    out.push('"');
199	    for c in text.chars() {
200	        match c {
201	            '\n' => out.push_str("\\n"),
202	            '\r' => out.push_str("\\r"),
203	            '\t' => out.push_str("\\t"),
204	            '"' => out.push_str("\\\""),
205	            '\\' => out.push_str("\\\\"),
206	            c if (c as u32) < 0x20 || c as u32 == 0x7f => {
207	                let _ = write!(out, "\\x{:02x}", c as u32);
208	            }
209	            c => out.push(c),
210	        }
211	    }
212	    out.push('"');
213	    out
214	}
215	
216	#[cfg(all(test, unix))]
217	mod path_render_tests {
218	    use super::render_path;
219	    use std::ffi::OsStr;
220	    use std::os::unix::ffi::OsStrExt;
221	
222	    fn r(raw: &[u8]) -> String {
223	        render_path(OsStr::from_bytes(raw))
224	    }
225	
226	    #[test]
227	    fn plain_ascii_and_ordinary_utf8_stay_bare() {
228	        assert_eq!(r(b"path/to/backup.key"), "path/to/backup.key");
229	        assert_eq!(r(b"-weird-name"), "-weird-name");
230	        // Decodable non-ASCII text is shown as itself, unquoted.
231	        assert_eq!(r("密钥/备份.key".as_bytes()), "密钥/备份.key");
232	    }
233	
234	    #[test]
235	    fn named_escapes_render_as_literal_two_char_sequences() {
236	        assert_eq!(r(b"a\nb"), r#""a\nb""#);
237	        assert_eq!(r(b"a\rb"), r#""a\rb""#);
238	        assert_eq!(r(b"a\tb"), r#""a\tb""#);
239	    }
240	
241	    #[test]
242	    fn quote_and_backslash_are_escaped_inside_quotes() {
243	        assert_eq!(r(b"a\"b"), r#""a\"b""#);
244	        assert_eq!(r(b"a\\b"), r#""a\\b""#);
245	    }
246	
247	    #[test]
248	    fn other_control_bytes_use_hex_and_split_no_lines() {
249	        assert_eq!(r(b"a\x1bb"), r#""a\x1bb""#); // ESC
250	        assert_eq!(r(b"\x00"), r#""\x00""#);
251	        assert_eq!(r(b"\x7f"), r#""\x7f""#);
252	        let rendered = r(b"a\x07\x1bc");
253	        assert!(
254	            !rendered.bytes().any(|b| b < 0x20 || b == 0x7f),
255	            "rendering must not retain raw control bytes: {rendered:?}"
256	        );
257	    }
258	
259	    #[test]
260	    fn invalid_utf8_bytes_use_hex_but_valid_text_around_remains() {
261	        assert_eq!(r(b"key-\xff"), r#""key-\xff""#);
262	        assert_eq!(r(b"key-\xff raw \xfe.bin"), r#""key-\xff raw \xfe.bin""#);
263	        assert_eq!(r(b"-\xffkey"), r#""-\xffkey""#);
264	        // A valid multibyte run next to a broken byte keeps its glyphs.
265	        let mut mixed = "密钥".as_bytes().to_vec();
266	        mixed.push(0xff);
267	        assert_eq!(r(&mixed), r#""密钥\xff""#);
268	        // Truncated multibyte lead/continuation bytes are each escaped.
269	        assert_eq!(r(b"\xe4\xbd"), r#""\xe4\xbd""#);
270	        assert_eq!(r(b"a\x80b"), r#""a\x80b""#);
271	    }
272	
273	    #[test]
274	    fn real_illegal_byte_differs_from_literal_backslash_text() {
275	        // A real 0xff byte ...
276	        assert_eq!(r(b"\xff"), r#""\xff""#);
277	        // ... is not the same visible target as a name containing the four
278	        // literal characters \, x, f, f.
279	        assert_eq!(r(b"\\xff"), r#""\\xff""#);
280	        assert_ne!(r(b"\xff"), r(b"\\xff"));
281	
282	        // Real newline vs the two characters backslash-n.
283	        assert_eq!(r(b"a\nb"), r#""a\nb""#);
284	        assert_eq!(r(b"a\\nb"), r#""a\\nb""#);
285	        assert_ne!(r(b"a\nb"), r(b"a\\nb"));
286	    }
287	
288	    #[test]
289	    fn distinct_illegal_bytes_do_not_share_a_rendering() {
290	        assert_eq!(r(b"key-\xff"), r#""key-\xff""#);
291	        assert_eq!(r(b"key-\xfe"), r#""key-\xfe""#);
292	        assert_ne!(r(b"key-\xff"), r(b"key-\xfe"));
293	    }
294	
295	    #[test]
296	    fn rendering_contains_no_raw_control_bytes_except_as_appended_newline() {
297	        for name in [
298	            &b"a\nb\x1bc\r\t"[..],
299	            &b"\x00\x01\x02\x1b\x7f"[..],
300	            &b"ok\xff\n"[..],
301	        ] {
302	            let rendered = r(name);
303	            assert!(
304	                !rendered.bytes().any(|b| b < 0x20 || b == 0x7f),
305	                "raw control byte survived in {rendered:?} for {name:?}"
306	            );
307	        }
308	    }
309	}
310	
311	#[cfg(unix)]
312	fn generate_key_file(path: &OsStr) -> std::io::Result<()> {
313	    // Use the raw OS bytes so a path containing non-UTF-8 bytes refers to
314	    // exactly the name the user passed, with no lossy substitution.
315	    let c_path = CString::new(path.as_bytes()).map_err(|_| {
316	        std::io::Error::new(
317	            std::io::ErrorKind::InvalidInput,
318	            "target path contains a NUL byte",
319	        )
320	    })?;
321	
322	    // Draw the key from the OS CSPRNG first. If the random source is
323	    // unavailable nothing is ever created at the target path.
324	    let mut key = [0u8; KEY_LEN];
325	    if let Err(e) = getrandom::fill(&mut key) {
326	        key.fill(0);
327	        return Err(std::io::Error::new(
328	            std::io::ErrorKind::Other,
329	            format!("cryptographic random source unavailable: {e}"),
330	        ));
331	    }
332	
333	    // O_CREAT | O_EXCL: fail if anything already exists at the path (file,
334	    // directory, or symlink -- including a dangling one, which O_NOFOLLOW
335	    // also rejects), so a pre-existing object is never overwritten or
336	    // followed. mode 0600 contains no group/other bits, and the umask can
337	    // only strip bits, never add them: group/other therefore never gain
338	    // access, not even for an instant. A strict umask (e.g. 0777) can also
339	    // strip the owner bits, leaving 0000; that is repaired with fchmod and
340	    // verified before any key byte is written (see ensure_owner_only_mode).
341	    let fd = unsafe {
342	        libc::open(
343	            c_path.as_ptr(),
344	            libc::O_WRONLY
345	                | libc::O_CREAT
346	                | libc::O_EXCL
347	                | libc::O_NOFOLLOW
348	                | libc::O_CLOEXEC,
349	            0o600,
350	        )
351	    };
352	    if fd < 0 {
353	        let e = std::io::Error::last_os_error();
354	        key.fill(0);
355	        return Err(std::io::Error::new(
356	            e.kind(),
357	            format!("cannot create key file {}: {e}", render_path(path)),
358	        ));
359	    }
360	    let fd = fd as RawFd;
361	
362	    // Enforce and confirm exactly 0600 before writing, then write and fsync.
363	    // On any failure the inode we just created is unlinked by abort_save; an
364	    // object predating this invocation is never touched.
365	    let outcome = ensure_owner_only_mode(fd).and_then(|()| write_key(fd, &key));
366	    key.fill(0);
367	
368	    match outcome {
369	        // The descriptor is still open: abort_save unlinks while it is (only
370	        // the link to the inode we just created is removed) and closes it
371	        // afterwards.
372	        Err(stage) => Err(abort_save(&c_path, path, Some(fd), stage)),
373	        Ok(()) => {
374	            // All 32 bytes were written and fsynced, but the save is only
375	            // finished once the close succeeds.
376	            if unsafe { libc::close(fd) } == 0 {
377	                return Ok(());
378	            }
379	            let e = std::io::Error::last_os_error();
380	            if e.raw_os_error() == Some(libc::EINTR) {
381	                // close() released the descriptor despite EINTR.
382	                return Ok(());
383	            }
384	            // An unrecoverable close error: even if the file happens to hold
385	            // 32 bytes with mode 0600, the save did not complete normally, so
386	            // this invocation's file must not stay behind to be mistaken for
387	            // a successfully saved key. On Linux the descriptor is released
388	            // even when close() reports an error, so close is not retried;
389	            // the file is removed exactly as for a write or fsync failure.
390	            let stage = std::io::Error::new(
391	                e.kind(),
392	                format!("closing the key file failed: {e}"),
393	            );
394	            Err(abort_save(&c_path, path, None, stage))
395	        }
396	    }
397	}
398	
399	/// Abandon a save that could not be completed: remove the file this
400	/// invocation created at the target and build the error to report.
401	///
402	/// `stage` is the original failure (permission setup or confirmation, write,
403	/// sync, or close); its kind and message are kept as the reported error, so a
404	/// cleanup problem can never mask why the save failed. If `fd` is `Some`, the
405	/// descriptor is still open: the unlink runs first and its result is captured
406	/// before the close, which may clobber errno (on Linux close releases the
407	/// descriptor even when it reports an error, so it is never retried).
408	///
409	/// The unlink only ever targets the link this invocation created (the caller
410	/// opened it O_CREAT | O_EXCL), never an object that predates this run.
411	///
412	/// * Removal succeeds: nothing of this run remains at the target -- no empty
413	///   file, no partial key, no unsynced 32-byte file.
414	/// * The system refuses the removal: whatever the file holds (an empty file,
415	///   a partial key, or 32 bytes that were never synced), it is not a saved
416	///   key. The report keeps the original failure, adds the cleanup failure
417	///   and its reason, and says plainly that this run's file may still sit at
418	///   the target so the user can check and remove it. It never claims the
419	///   file is gone, and the refusal is never worked around -- the parent
420	///   directory's permissions are not loosened and the key is not stashed
421	///   under another name.
422	#[cfg(unix)]
423	fn abort_save(
424	    c_path: &CString,
425	    path: &OsStr,
426	    fd: Option<RawFd>,
427	    stage: std::io::Error,
428	) -> std::io::Error {
429	    let unlink_err = if unsafe { libc::unlink(c_path.as_ptr()) } == 0 {
430	        None
431	    } else {
432	        Some(std::io::Error::last_os_error())
433	    };
434	    if let Some(fd) = fd {
435	        unsafe { libc::close(fd) };
436	    }
437	    let kind = stage.kind();
438	    match unlink_err {
439	        None => std::io::Error::new(
440	            kind,
441	            format!(
442	                "key file {} was not saved: {stage}; the file created by \
443	                 this invocation has been removed",
444	                render_path(path)
445	            ),
446	        ),
447	        Some(ue) => std::io::Error::new(
448	            kind,
449	            format!(
450	                "key file {} was not saved: {stage}; cleanup of the \
451	                 incomplete file also failed ({ue}): a file created by this \
452	                 failed run may still be present at the target -- check and \
453	                 remove it yourself",
454	                render_path(path)
455	            ),
456	        ),
457	    }
458	}
459	
460	#[cfg(unix)]
461	fn ensure_owner_only_mode(fd: RawFd) -> std::io::Result<()> {
462	    // The mode passed to open() is masked by the process umask, so a strict
463	    // umask (e.g. 0777) can strip the owner read/write bits, and some
464	    // filesystems may adjust or refuse the requested mode. fchmod on the
465	    // open fd is not affected by the umask: force exactly 0600 and then
466	    // fstat to confirm the filesystem actually stores those bits. This
467	    // runs before any key byte is written, so a file that cannot meet the
468	    // requirement never receives secret data.
469	    if unsafe { libc::fchmod(fd, 0o600) } != 0 {
470	        let e = std::io::Error::last_os_error();
471	        return Err(std::io::Error::new(
472	            e.kind(),
473	            format!(
474	                "cannot set key file permissions to 0600: {e} \
475	                 (filesystem does not support the required permissions)"
476	            ),
477	        ));
478	    }
479	
480	    let mut st: libc::stat = unsafe { std::mem::zeroed() };
481	    if unsafe { libc::fstat(fd, &mut st) } != 0 {
482	        // Without a fresh stat result the actual on-disk mode cannot be
483	        // confirmed, so the requirement cannot be met -- say so explicitly
484	        // rather than surface a bare errno string.
485	        let e = std::io::Error::last_os_error();
486	        return Err(std::io::Error::new(
487	            e.kind(),
488	            format!("cannot verify key file permissions are 0600: {e}"),
489	        ));
490	    }
491	
492	    // Exactly owner read/write, no group or other permissions of any kind.
493	    // This rejects 0400/0200/0000 (owner bits missing under a strict umask)
494	    // as well as any mode carrying group/other bits.
495	    if st.st_mode & 0o7777 != 0o600 {
496	        return Err(std::io::Error::new(
497	            std::io::ErrorKind::Other,
498	            format!(
499	                "cannot guarantee key file permissions 0600: \
500	                 filesystem reports mode 0{:04o}",
501	                st.st_mode & 0o7777
502	            ),
503	        ));
504	    }
505	    Ok(())
506	}
507	
508	#[cfg(unix)]
509	fn write_key(fd: RawFd, key: &[u8; KEY_LEN]) -> std::io::Result<()> {
510	    // Caller has already run ensure_owner_only_mode: the inode carries
511	    // exactly 0600 before the first secret byte reaches it. Failures are
512	    // labelled with the stage so the user can tell an unfinished write
513	    // apart from a permission or sync problem.
514	    write_all(fd, key).map_err(|e| {
515	        std::io::Error::new(e.kind(), format!("could not write key file: {e}"))
516	    })?;
517	
518	    if unsafe { libc::fsync(fd) } != 0 {
519	        let e = std::io::Error::last_os_error();
520	        return Err(std::io::Error::new(
521	            e.kind(),
522	            format!("could not flush key file: {e}"),
523	        ));
524	    }
525	
526	    Ok(())
527	}
528	
529	#[cfg(unix)]
530	fn write_all(fd: RawFd, mut data: &[u8]) -> std::io::Result<()> {
531	    while !data.is_empty() {
532	        let n = unsafe {
533	            libc::write(fd, data.as_ptr().cast::<libc::c_void>(), data.len())
534	        };
535	        if n < 0 {
536	            let e = std::io::Error::last_os_error();
537	            if e.raw_os_error() == Some(libc::EINTR) {
538	                continue;
539	            }
540	            return Err(e);
541	        }
542	        if n == 0 {
543	            return Err(std::io::Error::new(
544	                std::io::ErrorKind::WriteZero,
545	                "incomplete write to key file",
546	            ));
547	        }
548	        data = &data[n as usize..];
549	    }
550	    Ok(())
551	}
552	
553	#[cfg(not(unix))]
554	fn generate_key_file(_path: &OsStr) -> std::io::Result<()> {
555	    Err(std::io::Error::new(
556	        std::io::ErrorKind::Unsupported,
557	        "keygen is only supported on Unix systems",
558	    ))
559	}
