1	//! Regression coverage for keygen's contract when the OS cryptographic
2	//! random source cannot deliver the 32 key bytes (see README "拒绝覆盖与
3	//! 路径要求": 随机源不可用 must fail the command without leaving anything
4	//! behind).
5	//!
6	//! What is protected here:
7	//!
8	//! * If the random source fails before a single byte is delivered, keygen
9	//!   exits 1, explains on stderr that the cryptographic random source is
10	//!   unavailable, prints nothing on stdout, and creates nothing -- no empty
11	//!   file, no partial key, no stand-in key, no other new files.
12	//! * If the source delivers some bytes and then fails before the key is
13	//!   complete, the same holds: the partial material is never padded with
14	//!   zeroes into a saved file, and it never appears on stdout/stderr in raw
15	//!   or hex form.
16	//! * A source that only returns short reads is NOT a failure: the command
17	//!   keeps drawing until it has all 32 bytes and succeeds normally.
18	//! * The failure never disturbs pre-existing directory entries: siblings,
19	//!   the parent directory's permissions, an existing file at the target
20	//!   path, and a symlink (plus its referent) all survive byte-for-byte.
21	//! * The injection is scoped to the faulted run: with the shim loaded but
22	//!   no fault configured the real OS random source is used, --version and
23	//!   argument errors behave as published, and a retry after a transient
24	//!   failure succeeds.
25	//!
26	//! The faults are injected by the LD_PRELOAD shim tests/support/randtrap,
27	//! which traps the guest's getrandom(2) syscall with seccomp and emulates
28	//! it in a SIGSYS handler (the getrandom crate issues the syscall with
29	//! inline assembly, so symbol interposition cannot see it). Bytes the shim
30	//! hands out follow a fixed pattern (0x80, 0x81, ... by draw index) so the
31	//! tests can recognise them in files and output.
32	#![cfg(unix)]
33	
34	use std::fs;
35	use std::os::unix::fs::{MetadataExt, PermissionsExt};
36	use std::path::{Path, PathBuf};
37	use std::process::Command;
38	use std::sync::atomic::{AtomicU64, Ordering};
39	
40	const KEY_LEN: usize = 32;
41	const MODE_0600: u32 = 0o600;
42	const UMASKS: [u32; 3] = [0o022, 0o000, 0o777];
43	
44	fn bin() -> PathBuf {
45	    PathBuf::from(env!("CARGO_BIN_EXE_wrapfile"))
46	}
47	
48	fn randtrap_so() -> Option<PathBuf> {
49	    option_env!("WRAPFILE_RANDTRAP_SO").map(PathBuf::from)
50	}
51	
52	/// The byte the randtrap shim hands to the guest at global draw index `i`
53	/// (see pattern_byte() in randtrap.c).
54	fn pattern_byte(i: usize) -> u8 {
55	    (0x80 + (i % 64)) as u8
56	}
57	
58	/// The first `n` bytes the shim would deliver.
59	fn pattern(n: usize) -> Vec<u8> {
60	    (0..n).map(pattern_byte).collect()
61	}
62	
63	// ---------------------------------------------------------------------------
64	// scratch directory
65	// ---------------------------------------------------------------------------
66	
67	struct Tmp {
68	    path: PathBuf,
69	}
70	
71	impl Tmp {
72	    fn new(label: &str) -> Tmp {
73	        static SEQ: AtomicU64 = AtomicU64::new(0);
74	        let path = std::env::temp_dir().join(format!(
75	            "wrapfile-keygen-random-tests-{}-{}-{}",
76	            std::process::id(),
77	            label,
78	            SEQ.fetch_add(1, Ordering::Relaxed)
79	        ));
80	        fs::create_dir_all(&path).unwrap();
81	        fs::set_permissions(&path, fs::Permissions::from_mode(0o700)).unwrap();
82	        Tmp { path }
83	    }
84	
85	    fn child(&self, name: impl AsRef<Path>) -> PathBuf {
86	        self.path.join(name)
87	    }
88	}
89	
90	impl Drop for Tmp {
91	    fn drop(&mut self) {
92	        let _ = fs::set_permissions(&self.path, fs::Permissions::from_mode(0o700));
93	        let _ = fs::remove_dir_all(&self.path);
94	    }
95	}
96	
97	// ---------------------------------------------------------------------------
98	// running the binary
99	// ---------------------------------------------------------------------------
100	
101	struct Run {
102	    rc: i32,
103	    out: Vec<u8>,
104	    err: Vec<u8>,
105	}
106	
107	/// Run `wrapfile keygen <key>` after setting the umask inside a /bin/sh
108	/// wrapper, with the randtrap shim preloaded and a trace file configured.
109	fn run_keygen(key: &Path, umask: u32, so: &Path, extra_env: &[(&str, &str)], trace: &Path) -> Run {
110	    let mut cmd = Command::new("/bin/sh");
111	    cmd.arg("-c")
112	        .arg(format!("umask {umask:04o}; exec \"$@\""))
113	        .arg("sh")
114	        .arg(bin())
115	        .arg("keygen")
116	        .arg(key)
117	        .env("LD_PRELOAD", so)
118	        .env("WRAPFILE_TEST_TRACE_FILE", trace);
119	    for (k, v) in extra_env {
120	        cmd.env(k, v);
121	    }
122	    let o = cmd.output().unwrap();
123	    Run {
124	        rc: o.status.code().unwrap_or(-1),
125	        out: o.stdout,
126	        err: o.stderr,
127	    }
128	}
129	
130	/// Run `wrapfile <args...>` directly, with the randtrap shim preloaded.
131	fn run_bin(args: &[&str], so: &Path, extra_env: &[(&str, &str)], trace: &Path) -> Run {
132	    let mut cmd = Command::new(bin());
133	    cmd.args(args)
134	        .env("LD_PRELOAD", so)
135	        .env("WRAPFILE_TEST_TRACE_FILE", trace);
136	    for (k, v) in extra_env {
137	        cmd.env(k, v);
138	    }
139	    let o = cmd.output().unwrap();
140	    Run {
141	        rc: o.status.code().unwrap_or(-1),
142	        out: o.stdout,
143	        err: o.stderr,
144	    }
145	}
146	
147	// ---------------------------------------------------------------------------
148	// shim trace log
149	// ---------------------------------------------------------------------------
150	
151	/// Create the trace file up front (mode 0644) so that it stays readable
152	/// even when the child runs under umask 0777 -- the shim opens it O_APPEND.
153	fn prepare_trace(dir: &Path, name: impl AsRef<Path>) -> PathBuf {
154	    let p = dir.join(name);
155	    fs::File::create(&p).unwrap();
156	    fs::set_permissions(&p, fs::Permissions::from_mode(0o644)).unwrap();
157	    p
158	}
159	
160	/// False when the shim could not arm the seccomp trap on this system (or
161	/// was not loaded at all); the caller then skips instead of failing.
162	fn trap_armed(trace: &Path) -> bool {
163	    let text = fs::read_to_string(trace).unwrap();
164	    if text.lines().any(|l| l == "TRAP armed") {
165	        return true;
166	    }
167	    eprintln!("skipping: randtrap shim could not arm the seccomp trap here");
168	    false
169	}
170	
171	#[derive(Debug)]
172	struct GrEvent {
173	    req: usize,
174	    base: usize, // global draw index of the first byte this call hands out
175	    ret: i64,    // negative: the call failed with the injected errno
176	}
177	
178	impl GrEvent {
179	    fn failed(&self) -> bool {
180	        self.ret < 0
181	    }
182	
183	    fn delivered(&self) -> usize {
184	        if self.ret > 0 { self.ret as usize } else { 0 }
185	    }
186	
187	    /// The pattern bytes this call handed to the guest.
188	    fn bytes(&self) -> Vec<u8> {
189	        (self.base..self.base + self.delivered())
190	            .map(pattern_byte)
191	            .collect()
192	    }
193	}
194	
195	/// The GETRANDOM lines of the trace, in call order.
196	fn getrandom_events(trace: &Path) -> Vec<GrEvent> {
197	    let text = fs::read_to_string(trace).unwrap();
198	    text.lines()
199	        .filter_map(|line| {
200	            let mut parts = line.split_whitespace();
201	            if parts.next() != Some("GETRANDOM") {
202	                return None;
203	            }
204	            let mut req = None;
205	            let mut base = None;
206	            let mut ret = None;
207	            for kv in parts {
208	                let (k, v) = kv.split_once('=')?;
209	                match k {
210	                    "req" => req = v.parse().ok(),
211	                    "base" => base = v.parse().ok(),
212	                    "ret" => ret = v.parse().ok(),
213	                    _ => {}
214	                }
215	            }
216	            Some(GrEvent { req: req?, base: base?, ret: ret? })
217	        })
218	        .collect()
219	}
220	
221	/// The events that make up keygen's own draw of the 32 key bytes. The
222	/// process runtime may draw randomness of its own before main() (and the
223	/// getrandom crate probes the syscall once with a zero-length request), so
224	/// the key fill is identified as the final run of calls starting with a
225	/// full-length (32-byte) request.
226	fn key_fill_events(events: &[GrEvent]) -> &[GrEvent] {
227	    let start = events
228	        .iter()
229	        .rposition(|e| e.req == KEY_LEN)
230	        .expect("keygen must attempt to draw the 32 key bytes");
231	    &events[start..]
232	}
233	
234	/// The bytes the key fill received, reconstructed from the trace.
235	fn key_fill_bytes(events: &[GrEvent]) -> Vec<u8> {
236	    key_fill_events(events)
237	        .iter()
238	        .flat_map(GrEvent::bytes)
239	        .collect()
240	}
241	
242	// ---------------------------------------------------------------------------
243	// filesystem assertions
244	// ---------------------------------------------------------------------------
245	
246	fn mode_of(path: &Path) -> u32 {
247	    fs::symlink_metadata(path).unwrap().mode() & 0o7777
248	}
249	
250	fn contains_slice(haystack: &[u8], needle: &[u8]) -> bool {
251	    needle.is_empty() || haystack.windows(needle.len()).any(|w| w == needle)
252	}
253	
254	/// The failure contract for an unusable random source: exit 1, an
255	/// explanation naming the random source on stderr, nothing on stdout, and
256	/// no trace of this invocation left in the parent directory -- in
257	/// particular no file at the target path that could be mistaken for a key
258	/// (empty, partial, zero-padded, or a full-length stand-in).
259	fn assert_failed_random(key: &Path, run: &Run, dir: &Path, allowed_entries: &[&str]) {
260	    assert_eq!(run.rc, 1, "an unfinishable random draw must exit 1");
261	    assert!(
262	        run.out.is_empty(),
263	        "stdout must stay empty on random-source failure, got {}",
264	        String::from_utf8_lossy(&run.out)
265	    );
266	    let stderr = String::from_utf8_lossy(&run.err);
267	    assert!(
268	        stderr.contains("cryptographic random source unavailable"),
269	        "stderr must state that the cryptographic random source is \
270	         unavailable (without pinning the OS-specific error text), got: {stderr}"
271	    );
272	
273	    assert!(
274	        !key.exists(),
275	        "no file may be left at the target path after a random-source failure"
276	    );
277	    assert_no_leftovers(dir, allowed_entries);
278	}
279	
280	fn assert_no_leftovers(dir: &Path, allowed_entries: &[&str]) {
281	    let mut leftovers: Vec<String> = fs::read_dir(dir)
282	        .unwrap()
283	        .map(|e| e.unwrap().file_name().to_string_lossy().into_owned())
284	        .filter(|n| !allowed_entries.contains(&n.as_str()))
285	        .collect();
286	    leftovers.sort();
287	    assert!(leftovers.is_empty(), "unexpected leftover files: {leftovers:?}");
288	}
289	
290	// A pre-existing object that must survive a failed keygen byte-for-byte.
291	struct Sentinel {
292	    path: PathBuf,
293	    bytes: Vec<u8>,
294	    mode: u32,
295	    inode: u64,
296	}
297	
298	impl Sentinel {
299	    fn file(dir: &Path, name: &str, bytes: &[u8], mode: u32) -> Sentinel {
300	        let path = dir.join(name);
301	        fs::write(&path, bytes).unwrap();
302	        fs::set_permissions(&path, fs::Permissions::from_mode(mode)).unwrap();
303	        let meta = fs::metadata(&path).unwrap();
304	        Sentinel { path, bytes: bytes.to_vec(), mode, inode: meta.ino() }
305	    }
306	
307	    fn assert_untouched(&self) {
308	        let meta = fs::metadata(&self.path).expect("sentinel must still exist");
309	        assert_eq!(meta.ino(), self.inode, "sentinel inode changed (object replaced)");
310	        assert_eq!(meta.mode() & 0o7777, self.mode, "sentinel permissions changed");
311	        assert_eq!(fs::read(&self.path).unwrap(), self.bytes, "sentinel contents changed");
312	    }
313	}
314	
315	// ---------------------------------------------------------------------------
316	// tests
317	// ---------------------------------------------------------------------------
318	
319	#[test]
320	fn random_source_unavailable_before_any_byte_saves_nothing() {
321	    let Some(so) = randtrap_so() else {
322	        eprintln!("skipping: randtrap shim not available on this target");
323	        return;
324	    };
325	
326	    let tmp = Tmp::new("rand-fail-empty");
327	    let key = tmp.child("key");
328	    let sibling = Sentinel::file(&tmp.path, "sibling", b"do-not-touch", 0o644);
329	    let parent_mode_before = mode_of(&tmp.path);
330	    let trace = prepare_trace(&tmp.path, "trace.log");
331	
332	    // The random source reports it cannot deliver anything at all.
333	    let run = run_keygen(
334	        &key,
335	        0o022,
336	        &so,
337	        &[("WRAPFILE_TEST_GETRANDOM_FAIL", "1")],
338	        &trace,
339	    );
340	    if !trap_armed(&trace) {
341	        return;
342	    }
343	
344	    // The injected failure really was hit, before any key byte was drawn.
345	    let events = getrandom_events(&trace);
346	    let fill = key_fill_events(&events);
347	    assert!(
348	        fill.iter().all(GrEvent::failed),
349	        "no key byte may have been delivered in this scenario: {fill:?}"
350	    );
351	
352	    assert_failed_random(&key, &run, &tmp.path, &["sibling", "trace.log"]);
353	    sibling.assert_untouched();
354	    assert_eq!(
355	        mode_of(&tmp.path),
356	        parent_mode_before,
357	        "parent directory permissions must be untouched"
358	    );
359	
360	    // The failure was transient: a retry without the fault saves a full key.
361	    let trace2 = prepare_trace(&tmp.path, "trace2.log");
362	    let run2 = run_keygen(&key, 0o022, &so, &[], &trace2);
363	    assert_eq!(run2.rc, 0, "stderr={}", String::from_utf8_lossy(&run2.err));
364	    let bytes = fs::read(&key).unwrap();
365	    assert_eq!(bytes.len(), KEY_LEN, "the retry must save a full 32-byte key");
366	    assert_eq!(mode_of(&key), MODE_0600);
367	    sibling.assert_untouched();
368	}
