370	#[test]
371	fn random_source_failure_after_partial_bytes_saves_nothing() {
372	    let Some(so) = randtrap_so() else {
373	        eprintln!("skipping: randtrap shim not available on this target");
374	        return;
375	    };
376	
377	    let tmp = Tmp::new("rand-fail-partial");
378	    let key = tmp.child("key");
379	    let sibling = Sentinel::file(&tmp.path, "sibling", b"keep-me", 0o600);
380	    let parent_mode_before = mode_of(&tmp.path);
381	    let trace = prepare_trace(&tmp.path, "trace.log");
382	
383	    // The random source dries up after handing out 18 bytes in total: the
384	    // process runtime's own startup draw consumes some of that, and the
385	    // key fill gets the rest -- some bytes, but fewer than 32 -- before
386	    // the source fails for good.
387	    let run = run_keygen(
388	        &key,
389	        0o022,
390	        &so,
391	        &[("WRAPFILE_TEST_GETRANDOM_FAIL_AFTER", "18")],
392	        &trace,
393	    );
394	    if !trap_armed(&trace) {
395	        return;
396	    }
397	
398	    // The scenario really happened: the key fill drew some but not all of
399	    // the 32 bytes, and then the draw failed unrecoverably.
400	    let events = getrandom_events(&trace);
401	    let fill = key_fill_events(&events);
402	    let drawn = key_fill_bytes(&events);
403	    assert!(
404	        !drawn.is_empty() && drawn.len() < KEY_LEN,
405	        "the key fill must have drawn some but not all of the 32 bytes: {fill:?}"
406	    );
407	    assert!(
408	        fill.last().is_some_and(GrEvent::failed),
409	        "the key fill must have ended in the injected unrecoverable error: {fill:?}"
410	    );
411	
412	    assert_failed_random(&key, &run, &tmp.path, &["sibling", "trace.log"]);
413	    sibling.assert_untouched();
414	    assert_eq!(
415	        mode_of(&tmp.path),
416	        parent_mode_before,
417	        "parent directory permissions must be untouched"
418	    );
419	
420	    // The bytes already drawn are secret key material in waiting: they must
421	    // not leak to stdout/stderr, neither as raw bytes nor as text-encoded
422	    // (hex) diagnostics, and they must not be padded with zeroes into a
423	    // saved file -- there is no file at all.
424	    assert!(
425	        !contains_slice(&run.out, &drawn) && !contains_slice(&run.err, &drawn),
426	        "partially drawn random bytes must never appear on stdout/stderr"
427	    );
428	    let hex: String = drawn.iter().map(|b| format!("{b:02x}")).collect();
429	    assert!(
430	        !String::from_utf8_lossy(&run.out).contains(&hex)
431	            && !String::from_utf8_lossy(&run.err).contains(&hex),
432	        "partially drawn random bytes must not appear hex-encoded either"
433	    );
434	}
