437	fn short_reads_from_random_source_still_complete_the_key() {
438	    let Some(so) = randtrap_so() else {
439	        eprintln!("skipping: randtrap shim not available on this target");
440	        return;
441	    };
442	
443	    for umask in UMASKS {
444	        let tmp = Tmp::new("rand-short-reads");
445	        let key = tmp.child("key");
446	        let trace = prepare_trace(&tmp.path, "trace.log");
447	
448	        // A source that only ever returns 7 bytes per call but always
449	        // succeeds: not a failure, the command must keep drawing.
450	        let run = run_keygen(
451	            &key,
452	            umask,
453	            &so,
454	            &[("WRAPFILE_TEST_GETRANDOM_PARTIAL", "7")],
455	            &trace,
456	        );
457	        if !trap_armed(&trace) {
458	            return;
459	        }
460	
461	        assert_eq!(run.rc, 0, "stderr={}", String::from_utf8_lossy(&run.err));
462	        assert!(
463	            run.err.is_empty(),
464	            "stderr must be empty on success, got {}",
465	            String::from_utf8_lossy(&run.err)
466	        );
467	        assert_eq!(
468	            run.out,
469	            format!("Key saved to {}\n", key.display()).into_bytes(),
470	            "stdout must be exactly the save-location message"
471	        );
472	
473	        // Several short reads really happened and none was treated as a
474	        // failure.
475	        let events = getrandom_events(&trace);
476	        let fill = key_fill_events(&events);
477	        assert!(
478	            fill.len() >= 2,
479	            "short reads should mean multiple getrandom calls: {fill:?}"
480	        );
481	        assert!(
482	            fill.iter().all(|e| !e.failed() && e.delivered() <= 7),
483	            "every call was a successful short read: {fill:?}"
484	        );
485	
486	        // Every byte in the file came from the random source, in order --
487	        // nothing re-fetched, invented, or zero-padded.
488	        let expected = key_fill_bytes(&events);
489	        assert_eq!(expected.len(), KEY_LEN, "the draws must add up to 32 bytes");
490	        let bytes = fs::read(&key).unwrap();
491	        assert_eq!(bytes.len(), KEY_LEN, "key must be exactly 32 bytes");
492	        assert_eq!(
493	            bytes, expected,
494	            "the file must hold exactly the bytes the source delivered"
495	        );
496	        assert_eq!(
497	            mode_of(&key),
498	            MODE_0600,
499	            "key file mode must be exactly 0600 (umask {umask:04o})"
500	        );
501	    }
