498	#[test]
499	fn interrupted_writes_are_retried_until_the_key_is_saved() {
500	    let Some(so) = permfail_so() else {
501	        eprintln!("skipping: permfail shim not available on this target");
502	        return;
503	    };
504	
505	    let tmp = Tmp::new("eintr");
506	    let key = tmp.child("key");
507	    let trace = prepare_trace(&tmp.path, "trace.log");
508	
509	    // The first five write() calls are interrupted before any byte is
510	    // consumed; afterwards the system recovers (and still only takes three
511	    // bytes at a time). The same generation must complete, not fail.
512	    let run = run_keygen(
513	        &key,
514	        0o022,
515	        &so,
516	        &[
517	            ("WRAPFILE_TEST_WRITE_EINTR", "5"),
518	            ("WRAPFILE_TEST_PARTIAL_WRITE", "3"),
519	            ("WRAPFILE_TEST_TRACE_BYTES", "1"),
520	        ],
521	        &trace,
522	    );
523	
524	    let on_disk = assert_success(&key, &run);
525	
526	    let events = parse_trace(&trace);
527	    let eintrs = events
528	        .iter()
529	        .filter(|e| e.kind == "WRITE" && e.get("errno") == Some("EINTR"))
530	        .count();
531	    assert_eq!(eintrs, 5, "all injected EINTRs must have been observed");
532	
533	    // The interruption consumed nothing: the bytes that eventually landed
534	    // still tile [0, 32) exactly once and match the file.
535	    let writes = successful_writes(&events);
536	    assert_writes_tile(&writes, KEY_LEN, "writes after EINTR");
537	    assert_eq!(reconstruct(&writes), on_disk);
538	}
