541	fn unrecoverable_write_error_fails_and_removes_the_partial_file() {
542	    let Some(so) = permfail_so() else {
543	        eprintln!("skipping: permfail shim not available on this target");
544	        return;
545	    };
546	
547	    let tmp = Tmp::new("write-error");
548	    let key = tmp.child("key");
549	    let sibling = Sentinel::file(&tmp.path, "sibling", b"do-not-touch", 0o644);
550	    let parent_mode_before = mode_of(&tmp.path);
551	    let trace = prepare_trace(&tmp.path, "trace.log");
552	
553	    // Ten bytes land (4 + 4 + 2), then every further write fails with EIO.
554	    let run = run_keygen(
555	        &key,
556	        0o022,
557	        &so,
558	        &[
559	            ("WRAPFILE_TEST_PARTIAL_WRITE", "4"),
560	            ("WRAPFILE_TEST_FAIL_WRITE_AFTER", "10"),
561	            ("WRAPFILE_TEST_TRACE_BYTES", "1"),
562	        ],
563	        &trace,
564	    );
565	
566	    let events = parse_trace(&trace);
567	    let writes = successful_writes(&events);
568	    // The failure really happened mid-write: part of the key was on disk.
569	    assert_writes_tile(&writes, 10, "writes before the error");
570	    assert!(
571	        events
572	            .iter()
573	            .any(|e| e.kind == "WRITE" && e.get("errno") == Some("EIO")),
574	        "the unrecoverable write error must have been injected"
575	    );
576	    assert!(
577	        events.iter().all(|e| e.kind != "FSYNC"),
578	        "an incomplete key must never be synced as if complete"
579	    );
580	    let partial_key = reconstruct(&writes);
581	    assert_eq!(partial_key.len(), 10);
582	
583	    assert_failed_cleanly(&key, &run, &tmp.path, &["sibling", "trace.log"], &partial_key);
584	    sibling.assert_untouched();
585	    assert_eq!(
586	        mode_of(&tmp.path),
587	        parent_mode_before,
588	        "parent directory permissions must be untouched"
589	    );
590	
591	    // The failure was transient: a retry without the fault saves a full key.
592	    let trace2 = prepare_trace(&tmp.path, "trace2.log");
593	    let run2 = run_keygen(&key, 0o022, &so, &[], &trace2);
594	    assert_success(&key, &run2);
595	    sibling.assert_untouched();
596	}
