599	fn fsync_failure_after_full_write_fails_and_removes_the_file() {
600	    let Some(so) = permfail_so() else {
601	        eprintln!("skipping: permfail shim not available on this target");
602	        return;
603	    };
604	
605	    let tmp = Tmp::new("fsync-error");
606	    let key = tmp.child("key");
607	    let sibling = Sentinel::file(&tmp.path, "sibling", b"keep-me", 0o600);
608	    let parent_mode_before = mode_of(&tmp.path);
609	    let trace = prepare_trace(&tmp.path, "trace.log");
610	
611	    // All 32 bytes are written, but syncing them to disk fails.
612	    let run = run_keygen(
613	        &key,
614	        0o022,
615	        &so,
616	        &[
617	            ("WRAPFILE_TEST_FAIL_FSYNC", "1"),
618	            ("WRAPFILE_TEST_TRACE_BYTES", "1"),
619	        ],
620	        &trace,
621	    );
622	
623	    let events = parse_trace(&trace);
624	    let writes = successful_writes(&events);
625	    // The whole key was written before the sync failed...
626	    assert_writes_tile(&writes, KEY_LEN, "writes before fsync");
627	    assert!(
628	        events
629	            .iter()
630	            .any(|e| e.kind == "FSYNC" && e.ret() == Some(-1)),
631	        "the fsync failure must have been injected"
632	    );
