1201	        &tmp.path,
1202	        &["sibling", "trace.log"],
1203	        "incomplete write",
1204	    );
1205	    assert_key_material_not_leaked(&run, &full_key, "the rejected key");
1206	
1207	    // The residue really is the empty file this run created.
1208	    assert_eq!(
1209	        fs::read(&key).unwrap().len(),
1210	        0,
1211	        "the residue must be the empty file exactly as the failed run left it"
1212	    );
1213	    sibling.assert_untouched();
1214	    assert_eq!(
1215	        mode_of(&tmp.path),
1216	        parent_mode_before,
1217	        "parent directory permissions must never be loosened to force cleanup"
1218	    );
1219	
1220	    // Remove the residue manually; a fault-free retry then succeeds.
1221	    fs::remove_file(&key).unwrap();
1222	    let trace2 = prepare_trace(&tmp.path, "trace2.log");
1223	    let run2 = run_keygen(&key, 0o022, &so, &[], &trace2);
1224	    assert_success(&key, &run2);
1225	    sibling.assert_untouched();
